#!/bin/bash
# pasta-box chain (its plan is running) -> restart the server (upright term) -> cabinet with upright guidance -> jar over books (air)
cd /data/user_data/mbronars/packages/guided_playback; C=/data/user_data/mbronars/.miniconda3/envs/pwm211/bin/python
until [ -f runs/pickup/creative_pastabox_over_books/result.json ]; do sleep 20; done; echo "GEN creative_pastabox_over_books"
bash sweeps/obst_case_chain.sh creative_pastabox_over_books > logs/creative_pastabox_over_books_chain.log 2>&1 & CH=$!
until curl -s -m 5 http://babel-o9-24:8768/ | grep -q '"busy": false'; do sleep 10; done
for p in $(ps -eo pid,cmd | grep "bin/serve.py --adapter clean_pickup" | grep -v grep | awk '{print $1}'); do kill $p; done; sleep 8
CUDA_VISIBLE_DEVICES=0 nohup $C -u bin/serve.py --adapter clean_pickup --ckpt /data/user_data/mbronars/packages/pwm_final/runs/pickup_uncond_x0_regpass_cont200k/checkpoints/final.pt --port 8768 --warmup --warmup_transitions 60 --warmup_episodes 1,1,1,1 --warmup_iterations 1 > logs/serve_pickonly_o924_v4.log 2>&1 &
until grep -q -E "\[serve\] http|Traceback" logs/serve_pickonly_o924_v4.log; do sleep 10; done; echo "server up $(date)"
run(){ N=$1; [ -f runs/pickup/$N/result.json ] || $C bin/client.py http://babel-o9-24:8768/guide "$2" > logs/$N.req.json 2>&1; echo "GEN $N"; bash sweeps/obst_case_chain.sh $N > logs/${N}_chain.log 2>&1; echo "DONE $N"; }
run creative_carton_on_cabinet_upright '{"domain":"pickup","task":"wall","select":"/data/user_data/mbronars/packages/guided_playback/sweeps/assetsweep_select.json","episodes":"11,11,11,11","transitions":60,"steps":10,"offset":"0.30,0,0.196","optimizer":"adam","lr":0.1,"iterations":40,"shell":true,"box_weight":5,"clearance_mm":3,"wall_at":1.0,"upright_weight":0.3,"upright_frames":5,"seed":0,"wall_height":0.196,"wall_thickness":0.196,"wall_width":0.228,"obstacle_asset":"/data/group_data/katefgroup-ssd/sim_scene_gen/assets/libero/wooden_cabinet/asset_0170","obstacle_rpy":"0,0,90","obstacle_layout":"single","name":"creative_carton_on_cabinet_upright","desc":"milk carton placed on top of the wooden cabinet WITH an upright term (0.3 m/rad on the mean tilt of the last 5 frames); otherwise as creative_carton_on_cabinet"}'
run creative_jar_over_books_air '{"domain":"pickup","task":"wall","select":"/data/user_data/mbronars/packages/guided_playback/sweeps/assetsweep_select.json","episodes":"1,1,1,1","transitions":60,"steps":10,"offset":"0.30,0.03,0.15","optimizer":"adam","lr":0.1,"iterations":40,"shell":true,"box_weight":10,"clearance_mm":40,"seed":0,"wall_height":0.106,"wall_thickness":0.149,"wall_width":0.397,"obstacle_asset":"/data/group_data/katefgroup-ssd/sim_scene_gen/assets/libero/book/asset_0004","obstacle_rpy":"90,0,0","obstacle_layout":"rowstack:3:3","name":"creative_jar_over_books_air","desc":"peanut butter jar over a row of three stacks of three books midway, target +30 cm x +3 cm y and 15 cm in the air; Adam lr 0.1, 40 it, shell, wall weight 10, clearance (buffer) 40 mm, pop 4"}'
wait $CH; echo CASE_G_DONE
